//! UrDevice desktop app: a Slint window and a tray icon that show the core version.

// Hide the console window on Windows release builds.
#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]

use std::error::Error;

use slint::ComponentHandle;

mod tray;

/// Code generated by `slint-build` from `ui/main.slint`.
#[allow(clippy::all, clippy::unwrap_used, missing_debug_implementations)]
mod ui {
    slint::include_modules!();
}

use ui::MainWindow;

fn main() -> Result<(), Box<dyn Error>> {
    let version = urdevice_core::core_version();
    let platform = urdevice_platform::current();

    let window = MainWindow::new()?;
    window.set_core_version(version.into());
    window.set_platform_name(platform.name.into());

    // Keep the tray alive until the event loop ends. A missing tray (for example
    // GNOME without the AppIndicator extension) must not stop the app.
    let _tray = tray::install(version);

    window.run()?;
    Ok(())
}
